"""Prepare bilingual FIRST / Eubodio case studies and update their entry points."""
from pathlib import Path
from html import escape as esc
from PIL import Image
import re,json,hashlib,shutil
R=Path(__file__).resolve().parents[2];P=R/'public';A=P/'assets'
def asset_hash(path):return hashlib.sha256(path.read_bytes()).hexdigest()[:12]
model=A/'first/FIRST_THINGS_FIRST_DA_SCANSIONE_RESTAURO_WEB.glb';model_name=model.name
for name in ['new-case-studies.css','first-viewer.js']:
 p=A/name;dest=A/'static'/(p.stem+'-'+asset_hash(p)+p.suffix);dest.write_bytes(p.read_bytes())
css='/assets/static/new-case-studies-'+asset_hash(A/'new-case-studies.css')+'.css';js='/assets/first-scan-viewer.js'
font_html=re.search(r'<style data-local-fonts>.*?</style>',(P/'it/work/no-font/index.html').read_text(),re.S)[0]
def image(path,alt,eager=False,extra=''):
 p=P/path.lstrip('/');w,h=Image.open(p).size
 # Responsive delivery for the newly added assets, independent of gallery manifests.
 candidates=[]
 for size in [400,800,1200]:
  if size>=w:continue
  dst=p.with_name(p.stem+f'-{size}'+p.suffix)
  if not dst.exists():
   with Image.open(p) as im:
    im.thumbnail((size,10000));im.save(dst,'WEBP',quality=93,method=6)
  if dst.stat().st_size<p.stat().st_size*.9:candidates.append((size,'/'+dst.relative_to(P).as_posix()))
 candidates.append((w,path));srcset=','.join(u+' '+str(s)+'w' for s,u in candidates)
 return f'<img src="{path}" width="{w}" height="{h}" loading="{"eager" if eager else "lazy"}" decoding="async" alt="{esc(alt,quote=True)}" srcset="{srcset}" sizes="(max-width:800px) calc(100vw - 28px), min(100vw,1400px)" '+('fetchpriority="high" ' if eager else '')+extra+'>'
def fig(path,alt,caption,eager=False):return '<figure class="study-figure">'+image(path,alt,eager)+'<figcaption>'+esc(caption)+'</figcaption></figure>'
def frame(lang,slug,title,desc,body,og,scripts=''):
 pre='/it' if lang=='it' else '';other='' if pre else '/it';url='https://filippomantini.com'+pre+'/work/'+slug+'/'
 root=pre+'/';head=f'<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)} — Filippo Mantini</title><meta name="description" content="{esc(desc,quote=True)}"><link rel="canonical" href="{url}"><link rel="alternate" hreflang="it" href="https://filippomantini.com/it/work/{slug}/"><link rel="alternate" hreflang="en" href="https://filippomantini.com/work/{slug}/"><link rel="alternate" hreflang="x-default" href="https://filippomantini.com/work/{slug}/"><meta property="og:type" content="article"><meta property="og:title" content="{esc(title,quote=True)}"><meta property="og:description" content="{esc(desc,quote=True)}"><meta property="og:url" content="{url}"><meta property="og:image" content="https://filippomantini.com{og}"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/assets/static/project-5497922a5cc4.css"><link rel="stylesheet" href="{css}">{font_html}'
 schema={'@context':'https://schema.org','@type':'CreativeWork','name':title,'url':url,'creator':{'@type':'Person','name':'Filippo Mantini'},'inLanguage':lang,'description':desc}
 head+='<script type="application/ld+json">'+json.dumps(schema,ensure_ascii=False)+'</script></head>'
 nav=f'<body class="study"><div class="site-cursor" id="siteCursor" aria-hidden="true"></div><header class="topbar"><a class="name" href="{root}">FILIPPO MANTINI</a><nav aria-label="{"Navigazione" if pre else "Navigation"}"><a href="{root}#work">WORK</a><a href="{root}photography/">PHOTO</a><a href="{root}about/">ABOUT</a><a href="{other}/work/{slug}/">{"EN" if pre else "IT"}</a></nav><a class="back" href="{root}#work">← WORK</a></header>'
 footer=f'<footer class="footer"><span>Filippo Mantini © 2026</span><a href="mailto:info@filippomantini.com">info@filippomantini.com</a><a href="{root}privacy/">PRIVACY</a></footer><script src="/assets/static/project-cursor-10bb0092983c.js" defer></script>{scripts}</body></html>'
 return head+nav+'<main>'+body+'</main>'+footer

def first(lang):
 it=lang=='it';pre='/it' if it else ''
 t=lambda a,b:a if it else b
 title='First Things First'
 desc=t('Un oggetto tattile e un’identità visiva di Filippo Mantini. Una pausa da tenere in mano, tra ricerca sulla presa e composizione tipografica.','A tactile object and visual identity by Filippo Mantini. A pause to hold, explored through grip, form and typography.')
 controls=''.join(f'<button type="button" data-action="{action}" aria-label="{label}">{symbol}</button>' for action,label,symbol in [('left',t('Ruota a sinistra','Rotate left'),'←'),('right',t('Ruota a destra','Rotate right'),'→'),('up',t('Inclina verso l’alto','Tilt up'),'↑'),('down',t('Inclina verso il basso','Tilt down'),'↓'),('in',t('Ingrandisci','Zoom in'),'+'),('out',t('Riduci','Zoom out'),'−'),('reset',t('Ripristina la vista','Reset view'),'RESET')])
 viewer=f'<div class="first-stage" data-first-viewer data-model="/assets/first/{model_name}">{image("/assets/first/render-three-quarter.webp",t("Ricostruzione digitale dell’oggetto FIRST, vista a tre quarti","Digital reconstruction of FIRST, three-quarter view"),True)}<canvas hidden tabindex="0" role="img" aria-label="{t("Modello 3D FIRST. Frecce per ruotare, più e meno per zoom, Home per ripristinare.","FIRST 3D model. Arrow keys rotate, plus and minus zoom, Home resets.")}"></canvas><button type="button" data-load-model>{t("ESPLORA IN 3D","EXPLORE IN 3D")}</button><div class="model-controls" data-model-controls hidden>{controls}</div><p role="status" aria-live="polite">{t("Ruota la forma e osserva gli incavi della presa.","Rotate the form and explore the grip recesses.")}</p><noscript><p>{t("La vista interattiva richiede JavaScript. Le tavole mostrano lo stesso modello.","The interactive view requires JavaScript. The boards show the same model.")}</p></noscript></div>'
 body=f'<div class="study-kicker"><span>FIRST THINGS FIRST / FILIPPO MANTINI</span><span>OBJECT / VISUAL DESIGN</span></div><section class="first-hero"><div><h1 class="first-title"><span>FIRST</span><span>THINGS</span><span>FIRST.</span></h1><p class="first-lede">{t("Una pausa da tenere in mano.","A pause to hold.")}</p><p class="first-model-note">{t("Ricostruzione digitale interpretativa del progetto originale. La forma è ricavata dalle tavole e dalle fotografie di riferimento; non è una scansione del prototipo.","An interpretative digital reconstruction of the original design. The form is based on project boards and reference photographs; it is not a scan of the prototype.")}</p></div>{viewer}</section>'
 body+=f'<div class="study-meta"><div><b>{t("Ambito","Field")}</b>Object / Graphic design</div><div><b>{t("Autore","Author")}</b>Filippo Mantini</div><div><b>{t("Stato","Status")}</b>{t("Progetto sperimentale / prototipo realizzato","Experimental project / physical prototype")}</div></div>'
 body+=f'<section class="study-intro"><h2>{t("Prendersi un momento.<br>Attraverso un gesto.","Taking a moment.<br>Through a gesture.")}</h2><div class="study-copy"><p>{t("FIRST nasce per abitare i luoghi in cui ci fermiamo a lungo: una scrivania, un tavolo, un angolo di lavoro. È un oggetto da afferrare, sentire e lasciare andare, pensato per offrire una breve pausa nel ritmo della giornata.","FIRST belongs in the places where we spend time: a desk, a table, a corner of a workspace. It is an object to grasp, feel and put down, conceived as a brief pause in the rhythm of the day.")}</p><p>{t("Il progetto nasce dalla lettura di First Things First, di Stephen R. Covey, A. Roger Merrill e Rebecca R. Merrill. Ho tradotto l’idea di dare spazio a ciò che conta in una presenza fisica essenziale: la mano incontra la forma, le dita trovano gli incavi e l’attenzione torna per un istante al contatto.","The project began with First Things First by Stephen R. Covey, A. Roger Merrill and Rebecca R. Merrill. I translated the idea of making room for what matters into an essential physical presence: the hand meets the form, the fingers find its recesses and attention returns, for a moment, to touch.")}</p></div></section>'
 body+=f'<section class="first-red-board"><div><span class="study-label">01 / {t("IL GESTO","THE GESTURE")}</span><h2>{t("PRENDERE.<br>SENTIRE.<br>RIPARTIRE.","HOLD.<br>FEEL.<br>RETURN.")}</h2></div>{image("/assets/first/render-front.webp",t("Studio digitale della superficie e degli incavi FIRST","Digital study of the FIRST surface and grip recesses"))}</section>'
 body+=f'<section><h2 class="study-section-title">{t("La forma segue la presa.","The form follows the grip.")}</h2><div class="study-copy study-wide"><p>{t("Il volume verticale è interrotto da incavi per le dita e da una superficie irregolare che invita a esplorarlo. L’ergonomia è il punto di partenza della ricerca: costruire un rapporto immediato fra il palmo, la pressione e l’oggetto.","The upright volume is interrupted by finger recesses and an irregular surface that invites exploration. Ergonomics is the starting point of the study: establishing an immediate relationship between the palm, pressure and the object.")}</p></div><div class="first-views">'
 for name,label in [('front',t('01 / Incavi della presa','01 / Grip recesses')),('back',t('02 / Volume posteriore','02 / Rear volume')),('top',t('03 / Studio del volume','03 / Volume study'))]:body+=fig('/assets/first/render-'+name+'.webp',label,label)
 body+=f'</div><div class="first-dimensions"><div><strong>10.5 <span class="study-label">CM</span></strong><small>{t("ALTEZZA NOMINALE","NOMINAL HEIGHT")}</small></div><div><strong>5 <span class="study-label">CM</span></strong><small>{t("DIAMETRO NOMINALE","NOMINAL DIAMETER")}</small></div><p class="first-model-note">{t("Dimensioni riportate nelle tavole originali del progetto.","Dimensions recorded in the original project boards.")}</p></div></section>'
 body+=f'<section class="first-identity"><span class="study-label">02 / {t("IDENTITÀ VISIVA","VISUAL IDENTITY")}</span><h2 class="first-word-board"><span>FIRST</span><span>THINGS</span><span>FIRST</span></h2><p class="first-identity-note">{t("Rosso, nero e parole che cambiano scala. La ricerca sull’oggetto continua nella grafica: il nome si scompone, si ricompone e costruisce una presenza riconoscibile, come la scritta attorno alla base.","Red, black and words that change scale. The object study continues through graphics: the name breaks apart and recombines into a recognisable presence, echoing the lettering around the base.")}</p></section><p class="first-closing">{t("FIRST propone un piccolo rituale quotidiano: ritrovare il piacere di un gesto semplice, prima di tornare a ciò che stiamo facendo.","FIRST proposes a small daily ritual: rediscovering the pleasure of a simple gesture before returning to what we are doing.")}</p><section class="next"><small>{t("Altro progetto","Another project")}</small><a href="{pre}/work/no-font/">NO FONT</a></section>'
 return frame(lang,'first-things-first',title,desc,body,'/assets/first/render-three-quarter.webp',f'<script src="{js}" defer></script>')

def eubodio(lang):
 it=lang=='it';pre='/it' if it else '';t=lambda a,b:a if it else b;slug='collapse/collections/eubodio';desc=t('Eubodio, una capsule COLLAPSE di 30 pezzi unici. Superfici urbane, vernice serigrafica e tracce trasferite sui capi.','Eubodio, a COLLAPSE capsule of 30 unique pieces. Urban surfaces, screen-printing ink and traces transferred onto garments.')
 body=f'<div class="study-kicker"><a href="{pre}/work/collapse/">← COLLAPSE / COLLECTION</a><span>CAPSULE / 30 {t("PEZZI UNICI","UNIQUE PIECES")}</span></div><section class="eub-hero"><h1>EUBODIO</h1><div class="study-copy study-wide"><p>{t("La città lascia il segno.","The city leaves its mark.")}</p></div><div class="study-wide">{fig("/assets/collapse/eubodio/campaign-01.webp",t("Archivio Eubodio: capi e superfici urbane","Eubodio archive: garments and urban surfaces"),"EUBODIO / COLLAPSE",True)}</div></section>'
 body+=f'<section class="study-intro"><h2>{t("Dalla superficie.<br>Al capo.","From surface.<br>To garment.")}</h2><div class="study-copy"><p>{t("Eubodio è una capsule COLLAPSE nata per dare visibilità agli elementi urbani che attraversiamo senza guardarli: tombini, grate, cassette e pavimentazioni diventano una matrice di stampa.","Eubodio is a COLLAPSE capsule that brings attention to urban elements we pass without noticing: manhole covers, grilles, utility boxes and paving become printing matrices.")}</p><p>{t("Sulle superfici selezionate è stata applicata vernice serigrafica a base d’acqua, rimossa dopo l’utilizzo. La traccia viene trasferita sul tessuto: un contatto diretto tra il capo e la città, da cui nascono 30 pezzi unici.","Water-based screen-printing ink was applied to selected surfaces and removed after use. Their traces were transferred onto fabric: direct contact between garment and city, resulting in 30 unique pieces.")}</p><p>{t("Le cartoline originali accompagnano la serie con una numerazione da 1 a 30. Il valore di ogni capo sta nella sua impronta specifica, nelle irregolarità e nella posizione della stampa.","The original postcards accompany the series with numbering from 1 to 30. Each garment is defined by its particular imprint, its irregularities and the placement of the print.")}</p></div></section>'
 body+=f'<div class="study-meta"><div><b>COLLAPSE</b>Co-Founder / Creative Director</div><div><b>{t("Ambito","Field")}</b>{t("Ricerca visiva / Capsule / Comunicazione","Visual research / Capsule / Communication")}</div><div><b>{t("Serie documentata","Documented edition")}</b>30 {t("pezzi unici","unique pieces")}</div></div><h2 class="study-section-title">01 / {t("Le matrici della città.","The city as a matrix.")}</h2><div class="eub-sources">'
 labels=[t('Cassetta postale','Post box'),t('Cestino urbano','Street bin'),t('Chiusino circolare','Round cover'),t('Pavimentazione','Paving'),t('Chiusino decorato','Patterned cover'),t('Porta e dettagli urbani','Door and urban details')]
 for i,label in enumerate(labels,1):body+=fig(f'/assets/collapse/eubodio/urban-{i:02}.webp',label,label)
 body+=f'</div><h2 class="study-section-title">02 / {t("Il trasferimento.","The transfer.")}</h2><div class="study-pair">{fig("/assets/collapse/eubodio/printing-process.webp",t("Materiali e capo durante il processo di stampa Eubodio","Materials and garment during the Eubodio printing process"),t("PROCESSO / DOCUMENTAZIONE ORIGINALE","PROCESS / ORIGINAL DOCUMENTATION"))}{fig("/assets/collapse/eubodio/print-detail.webp",t("Dettaglio dell’impronta su tessuto Eubodio","Close-up of an Eubodio imprint on fabric"),t("SUPERFICIE → TESSUTO","SURFACE → FABRIC"))}</div><h2 class="study-section-title">03 / {t("Una serie, impronte diverse.","One series, different imprints.")}</h2><div class="eub-products">'
 for i in range(1,28):body+=fig(f'/assets/collapse/eubodio/garment-{i:02}.webp',t(f'Eubodio, studio di capo {i:02}',f'Eubodio, garment study {i:02}'),f'EUBODIO / {i:02}')
 body+=f'</div><h2 class="study-section-title">04 / {t("L’archivio diventa comunicazione.","The archive becomes communication.")}</h2><div class="study-pair">{fig("/assets/collapse/eubodio/campaign-02.webp",t("Composizione editoriale dei capi Eubodio e delle superfici di origine","Editorial composition of Eubodio garments and source surfaces"),"EUBODIO / ARCHIVE")}{fig("/assets/collapse/eubodio/poster.webp",t("Poster originale COLLAPSE Everything Collapse On Earth","Original COLLAPSE Everything Collapse On Earth poster"),"EVERYTHING COLLAPSE ON EARTH / ORIGINAL POSTER")}</div><section class="next"><small>{t("Torna al progetto","Back to the project")}</small><a href="{pre}/work/collapse/">COLLAPSE</a></section>'
 return frame(lang,slug,'Eubodio / COLLAPSE',desc,body,'/assets/collapse/eubodio/campaign-01.webp')

for lang in ['it','en']:
 pre='it/' if lang=='it' else ''
 for slug,content in [('first-things-first',first(lang)),('collapse/collections/eubodio',eubodio(lang))]:
  path=P/pre/'work'/slug/'index.html';path.parent.mkdir(parents=True,exist_ok=True);path.write_text(content)
 # Explain No Font using the author's own original about boards.
 p=P/pre/'work/no-font/index.html';s=p.read_text();it=lang=='it'
 intro=('Ho preso come riferimento la struttura narrativa di Mr. Nobody, in cui le scelte del protagonista aprono storie parallele. No Font porta questa idea nella composizione tipografica: le stesse lettere possono costruire letture diverse.' if it else 'I took the narrative structure of Mr. Nobody as a starting point: the protagonist’s choices open up parallel stories. No Font brings this idea into typography, allowing the same letters to produce different readings.')
 method=('I tagli delle lettere diventano punti d’incastro. Con una spaziatura regolare l’alfabeto rimane leggibile; avvicinando, ruotando e sovrapponendo i glifi, il testo diventa una composizione aperta. Lo specimen mette alla prova queste possibilità attraverso lettere, numeri e segni.' if it else 'Cuts in the letterforms become interlocking points. Regular spacing keeps the alphabet readable; bringing glyphs closer, rotating and overlapping them turns text into an open composition. The specimen explores these possibilities through letters, numerals and signs.')
 s=re.sub(r'<section class="nofont-intro">.*?</section>',f'<section class="nofont-intro"><h2>{"UNA LETTERA.<br>PIÙ POSSIBILITÀ." if it else "ONE LETTER.<br>MORE POSSIBILITIES."}</h2><div><p>{intro}</p><p>{method}</p><div class="type-related"><a href="/{pre}work/citta-di-castello/">{"Prova anche l’alfabeto CDC" if it else "Try the CDC alphabet"}</a></div></div></section>',s,count=1,flags=re.S)
 s=s.replace('<h1>NO FONT</h1>','<h1 class="nofont-type-title">NO FONT</h1>')
 if css not in s:s=s.replace('</head>',f'<link rel="stylesheet" href="{css}"></head>')
 p.write_text(s)
 # Add FIRST as a distinct object-design project, outside the selected-work numbering.
 p=P/pre/'index.html';s=p.read_text()
 if '/work/first-things-first/' not in s:
  row=f'<a class="archive-row" href="/{pre}work/first-things-first/" aria-label="{"Apri" if it else "View"} First Things First"><span class="n">12</span><span class="t">First Things First</span><span class="type">Object / Graphic Design</span></a>'
  anchor=re.search(r'<a class="archive-row"[^>]*href="[^"]*/work/no-font/".*?</a>',s,re.S);assert anchor;s=s[:anchor.end()]+row+s[anchor.end():]
 p.write_text(s)
 # Preserve current collections and add the historical capsule after them.
 p=P/pre/'work/collapse/index.html';s=p.read_text()
 if '/collections/eubodio/' not in s:
  anchor=re.search(r'<a class="cp-collection"[^>]*href="[^"]*/collections/fw23-24/".*?</a>',s,re.S);assert anchor
  card=f'<a class="cp-collection" href="/{pre}work/collapse/collections/eubodio/"><span class="cp-collection-year">ARCHIVE</span><strong>EUBODIO</strong><p>{"30 pezzi unici. La città come matrice di stampa." if it else "30 unique pieces. The city as a printing matrix."}</p><span class="cp-collection-arrow" aria-hidden="true">↗</span></a>'
  s=s[:anchor.end()]+card+s[anchor.end():]
 p.write_text(s)
p=P/'sitemap.xml';s=p.read_text()
for lang in ['','it/']:
 for slug in ['first-things-first','collapse/collections/eubodio']:
  url=f'https://filippomantini.com/{lang}work/{slug}/'
  if url not in s:s=s.replace('</urlset>',f'  <url><loc>{url}</loc></url>\n</urlset>')
p.write_text(s)
print('Prepared four new bilingual pages, No Font explanations and entry points.')
